package com.acme.parking.entry;

/**
 * Blocks vehicle entry when the zone's capacity is already reached.
 */
public class ZoneCapacityGuard {

    private final ZoneOccupancyRepository occupancy;
    private final ZoneRepository zones;

    public ZoneCapacityGuard(ZoneOccupancyRepository occupancy, ZoneRepository zones) {
        this.occupancy = occupancy;
        this.zones = zones;
    }

    public void assertSpaceAvailable(String zoneId) {
        int capacity = zones.require(zoneId).getCapacity();
        int current = occupancy.currentCount(zoneId);
        if (current >= capacity) {
            throw new ZoneFullException(zoneId, current, capacity);
        }
    }
}

class ZoneFullException extends RuntimeException {
    public ZoneFullException(String zoneId, int current, int capacity) {
        super("Zone " + zoneId + " is full (" + current + "/" + capacity + ")");
    }
}

