package com.acme.parking.pricing;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Duration;

/**
 * Calculates parking charge from duration, hourly rate and daily cap.
 */
public class ParkingChargeCalculator {

    private final ZoneRepository zones;

    public ParkingChargeCalculator(ZoneRepository zones) {
        this.zones = zones;
    }

    public BigDecimal charge(String zoneId, Duration duration) {
        Zone zone = zones.require(zoneId);
        long hours = Math.max(1, (long) Math.ceil(duration.toMinutes() / 60.0));
        BigDecimal raw = zone.getHourlyRate().multiply(BigDecimal.valueOf(hours));
        return raw.min(zone.getDailyCap()).setScale(2, RoundingMode.HALF_UP);
    }
}

