package com.acme.parking.payment;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * Handles pay-station payment: charge computation, payment recording, exit voucher.
 */
public class PayStationService {

    private final TicketRepository tickets;
    private final ParkingChargeCalculator charges;
    private final PaymentGateway paymentGateway;
    private final ExitVoucherRepository vouchers;

    public PayStationService(TicketRepository tickets, ParkingChargeCalculator charges,
                             PaymentGateway paymentGateway, ExitVoucherRepository vouchers) {
        this.tickets = tickets;
        this.charges = charges;
        this.paymentGateway = paymentGateway;
        this.vouchers = vouchers;
    }

    public ExitVoucher pay(String ticketCode, String paymentMethod) {
        Ticket t = tickets.require(ticketCode);
        if (t.isPaid()) {
            throw new IllegalStateException("Ticket already paid");
        }
        BigDecimal amount = charges.charge(t.getZoneId(), java.time.Duration.between(t.getIssuedAt(), Instant.now()));
        PaymentResult result = paymentGateway.charge(paymentMethod, amount);
        if (!result.isSuccessful()) {
            throw new PaymentFailedException(result.getFailureReason());
        }
        t.markPaid(Instant.now());
        tickets.save(t);
        return vouchers.issue(t.getId(), amount);
    }
}

