package com.acme.parking.driver;

import java.time.Duration;
import java.time.Instant;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * Current session view: remaining time until expiry.
 */
@RestController
public class ActiveSessionController {

    private final TicketRepository tickets;

    public ActiveSessionController(TicketRepository tickets) {
        this.tickets = tickets;
    }

    @GetMapping("/sessions/active")
    public ActiveSessionView active(@RequestParam String ticketCode) {
        Ticket t = tickets.require(ticketCode);
        if (!t.isActive()) {
            throw new NoActiveSessionException(ticketCode);
        }
        Duration remaining = Duration.between(Instant.now(), t.getExpiresAt());
        if (remaining.isNegative()) {
            remaining = Duration.ZERO;
        }
        return new ActiveSessionView(ticketCode, t.getZoneId(), t.getExpiresAt(), remaining);
    }
}

