/**
 * Extends an active parking session by an additional duration.
 */
public class SessionExtensionService {

    private final TicketRepository tickets;
    private final ParkingChargeCalculator charges;
    private final PaymentGateway paymentGateway;

    public SessionExtensionService(TicketRepository tickets, ParkingChargeCalculator charges, PaymentGateway paymentGateway) {
        this.tickets = tickets;
        this.charges = charges;
        this.paymentGateway = paymentGateway;
    }

    public Ticket extend(String ticketCode, Duration extraTime, String paymentMethod) {
        Ticket t = tickets.require(ticketCode);
        if (!t.isActive()) {
            throw new IllegalStateException("Session is not active");
        }
        var amount = charges.charge(t.getZoneId(), extraTime);
        var result = paymentGateway.charge(paymentMethod, amount);
        if (!result.isSuccessful()) {
            throw new PaymentFailedException(result.getFailureReason());
        }
        t.setExpiresAt(t.getExpiresAt().plus(extraTime));
        tickets.save(t);
        return t;
    }
}

