package com.acme.parking.audit;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Persists a reconciliation record for each parking event.
 */
public class ParkingEventRecorder {

    private final EntityManager em;

    public ParkingEventRecorder(EntityManager em) {
        this.em = em;
    }

    public void record(String vehiclePlate, String zoneId, String eventType, String actorId) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            ParkingEventEntry e = new ParkingEventEntry();
            e.setVehiclePlate(vehiclePlate);
            e.setZoneId(zoneId);
            e.setEventType(eventType);
            e.setActorId(actorId);
            e.setOccurredAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

