#include <stdio.h>
#include "parking_db.h"

int write_zone_reconciliation(const char *day, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "zone_id,entries,exits,charges_collected,penalties_issued\n");

    db_cursor_t *cur = NULL;
    if (db_open_zone_daily_cursor(&cur, day) != DB_OK) { fclose(out); return -2; }

    int rows = 0;
    zone_daily_row_t row;
    while (db_zone_daily_cursor_next(cur, &row) == DB_OK) {
        fprintf(out, "%s,%d,%d,%.2f,%d\n",
                row.zone_id, row.entries, row.exits, row.charges_collected, row.penalties_issued);
        rows++;
    }
    db_close_cursor(cur);
    fclose(out);
    return rows;
}

